function Confirm-Irreversible { Read-Host 'type the name' }
function Invoke-UnattendedRun { param() }
# STAGES
$old = 'OldUbuntu'
Invoke-UnattendedRun -ResultDirectory (Join-Path (Get-Location) 'unattended-results') -Irreversible 'wsl --unregister OldUbuntu' -Stages {
    Assert-Elevation -Mode Forbidden
    Assert-NotInside -Name 'Ubuntu'
    Invoke-IdempotentStep -Name 'restart Ubuntu' -Done { $false } -Action {
        wsl.exe --terminate Ubuntu
        wsl.exe -d Ubuntu -- true
    }
    $names = Invoke-NativeUtf8 { wsl.exe --list --quiet }
    Assert-ParsedState -Name 'wsl --list' -Value $names
    Confirm-Irreversible -Name 'wsl --unregister OldUbuntu'
    Invoke-IdempotentStep -Name 'unregister OldUbuntu' -Done { $names -notcontains $old } -Action {
        wsl.exe --unregister $old
    }
    $null = Wait-ForState -Name 'OldUbuntu removed' -Predicate {
        $now = @(Invoke-NativeUtf8 { wsl.exe --list --quiet })
        $now.Count -gt 0 -and $now -notcontains $old
    }
}

