# STAGES
Invoke-UnattendedRun -ResultDirectory (Join-Path $PSScriptRoot 'unattended-results') `
    -Irreversible 'wsl --unregister OldUbuntu' `
    -Stages {
    # Restarting Ubuntu or unregistering OldUbuntu from inside either would cut off the script.
    Assert-NotInside -Name 'Ubuntu'
    Assert-NotInside -Name 'OldUbuntu'

    # Read-only listings. wsl.exe output is pinned to UTF-8; a failed read throws,
    # so an error message is never parsed as a distro list.
    $getRegistered = {
        $lines = Invoke-NativeUtf8 { $global:LASTEXITCODE = 0; wsl.exe --list --quiet }
        if ($LASTEXITCODE -ne 0) { throw "wsl --list failed: exit $LASTEXITCODE" }
        Assert-ParsedState -Name 'registered distros' -Value $lines
        @($lines | ForEach-Object { "$_".Trim() } | Where-Object { $_ })
    }
    $getRunning = {
        $lines = Invoke-NativeUtf8 { $global:LASTEXITCODE = 0; wsl.exe --list --running --quiet }
        if ($LASTEXITCODE -ne 0) { throw "wsl --list --running failed: exit $LASTEXITCODE" }
        @($lines | ForEach-Object { "$_".Trim() } | Where-Object { $_ })
    }

    Add-Preflight -Name 'Ubuntu is registered' -Fix 'Install or rename the distro so that "wsl --list" shows Ubuntu' -Test {
        (& $getRegistered) -contains 'Ubuntu'
    }

    # 1. Restart Ubuntu: terminate it, then start it again.
    Invoke-IdempotentStep -Name 'terminate Ubuntu' -Done { $false } -Action {
        wsl.exe --terminate Ubuntu
    }
    Invoke-IdempotentStep -Name 'start Ubuntu' -Done { $false } -Action {
        wsl.exe -d Ubuntu --exec /bin/true
    }
    $null = Wait-ForState -Name 'Ubuntu running' -TimeoutSeconds 60 -Predicate {
        $running = @(& $getRunning)
        $running.Count -gt 0 -and $running -contains 'Ubuntu'
    }

    # 2. Unregister OldUbuntu, only if it still exists. Irreversible, so it goes last.
    $oldExists = (& $getRegistered) -contains 'OldUbuntu'
    if ($oldExists) {
        Confirm-Irreversible -Name 'wsl --unregister OldUbuntu'
    }
    Invoke-IdempotentStep -Name 'unregister OldUbuntu' -Done { -not $oldExists } -Action {
        wsl.exe --unregister OldUbuntu
    }
    if ($oldExists) {
        $null = Wait-ForState -Name 'OldUbuntu gone' -TimeoutSeconds 60 -Predicate {
            $names = @(& $getRegistered)
            $names.Count -gt 0 -and $names -notcontains 'OldUbuntu'
        }
    }
}

